package main

import \"testing\"

func TestGliderRepeatsAfterFourSteps(t *testing.T) {
	// Glider pattern placed at top-left.
	g := NewGrid(8, 8)
	g.LoadPattern(0, 0, "'`..O
O.O
.OO`)
	start := g.Render()
	for i := 0; i < 4; i++ {
		g.Step()
	}
	if g.Render() != start {
		t.Fatalf("glider did not return to start after 4 steps:'"\\n%s\", g.Render())
	}
}

func TestBlinker(t *testing.T) {
	g := NewGrid(5, 5)
	g.LoadPattern(1, 1, "'`OOO`)
	g.Step()
	want := `.....
.....
..O..
..O..
..O..
`
	if g.Render() != want {
		t.Fatalf("blinker phase wrong:'"\\n%s\", g.Render())
	}
}

func TestStillLifeBlock(t *testing.T) {
	g := NewGrid(5, 5)
	g.LoadPattern(1, 1, "'`OO
OO`)
	g.Step()
	if g.Render() != g.Render() {
		t.Fatal("unreachable")
	}
	// block is a still life: alive count stays 4 but rebuild check
	if g.Alive() != 4 {
		t.Fatalf("expected 4 alive, got %d", g.Alive())
	}
}
